import {prepareMaterialProperties,mountMaterialPropertyEditor,materialPropertyIssues} from '../editor/material-properties.js';
import {configKey,molecularTasks,submitMolecularTask} from './molecular-tasks.js';
import {openMicroModeling} from '../editor/micro-modeling-dialog.js';
import {esc} from '../editor/model.js';
import {icon} from '../../shared/icons.js';
export function renderMolecularPage(name){return `<main class="molecular-page"><header class="molecular-page-bar"><button class="btn" data-molecular-back>${icon('chevron')}返回建模</button><strong>${esc(name)}</strong><button class="icon-btn" title="材料库（示意）" aria-label="材料库（示意）">${icon('file')}</button><button class="icon-btn" title="导入分子（示意）" aria-label="导入分子（示意）">${icon('upload')}</button><button class="btn primary" data-molecular-save>${icon('check')}保存模型</button><button class="btn" data-molecular-config>${icon('flow')}参数设置</button><button class="btn primary" data-molecular-submit disabled>${icon('play')}提交计算</button></header><div class="molecular-page-content"></div><section class="molecular-linked-tasks" aria-label="此模型的计算任务"></section></main>`;}
export function mountMolecularPage(root,initial,{onSave,navigate,openDialog,notify,modelId}){
 let view,closed=false,saving=false,applied=false,current=structuredClone(initial),settings=null;try{settings=JSON.parse(localStorage.getItem(configKey(modelId))||'null');}catch{}
 const cleanup=()=>{if(!closed){closed=true;view?.dispatchEvent(new Event('close'));}};
 const close=()=>{if(saving)return;cleanup();navigate('/models');};
 view=openMicroModeling(html=>{const el=document.createElement('div');el.className='molecular-page-editor';el.innerHTML=html;el.close=close;root.querySelector('.molecular-page-content').append(el);el.addEventListener('click',e=>{if(e.target.closest('[data-dialog-close]'))close();});return el;},initial,{title:initial.name,materialName:'',onApply:m=>{current=structuredClone(m);onSave(m);applied=true;}});
 root.querySelector('[data-molecular-back]').onclick=close;
 const saveCurrent=()=>{applied=false;saving=true;try{view.querySelector('[data-apply-molecule]').click();}finally{saving=false;}return applied;};
 root.querySelector('[data-molecular-save]').onclick=saveCurrent;
 const submit=root.querySelector('[data-molecular-submit]');submit.disabled=!settings;
 root.querySelector('[data-molecular-config]').onclick=()=>{const draft=structuredClone(settings||{name:current.name,keyProperty:'tg',propertyConfigs:{}});prepareMaterialProperties(draft,{params:{case:'generic'}});const d=openDialog(`<form class="dialog-form material-compute-form"><h2>关键物性参数</h2><p class="macro-note">${esc(current.name)} · 与跨尺度建模使用相同的参数设置</p><div data-molecule-properties></div><p class="macro-error" role="alert"></p><div class="dialog-actions"><button type="button" class="btn" data-dialog-close>取消</button><button class="btn primary">保存参数</button></div></form>`);d.classList.add('material-compute-dialog');const editor=mountMaterialPropertyEditor(d.querySelector('[data-molecule-properties]'),()=>draft,'generic');editor.render();d.querySelector('form').onsubmit=e=>{e.preventDefault();editor.collect();const errors=materialPropertyIssues(draft,'generic');if(errors.length){d.querySelector('.macro-error').textContent=errors.map(x=>x.join('：')).join('；');return;}settings=draft;localStorage.setItem(configKey(modelId),JSON.stringify(settings));submit.disabled=false;d.close();notify('参数已保存，可以提交计算');};};
 const renderTasks=()=>{const tasks=molecularTasks().filter(t=>t.modelId===modelId);root.querySelector('.molecular-linked-tasks').innerHTML=`<header><h2>关联计算任务 <small>${tasks.length}</small></h2><button class="btn" data-molecular-tasks>任务管理</button></header>${tasks.length?`<div class="molecular-task-table"><table><thead><tr><th>任务</th><th>物性 / 方法</th><th>状态</th><th>进度</th><th>提交时间</th><th></th></tr></thead><tbody>${tasks.map(t=>`<tr><td>${esc(t.name)}<small>${esc(t.id)}</small></td><td>${esc(t.property)} / ${esc(t.method)}</td><td>${esc(t.status)}</td><td>${t.progress}%</td><td>${esc(t.time)}</td><td><button class="btn" data-molecular-task="${esc(t.id)}">参数快照</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="molecular-task-empty">尚无计算任务。设置关键物性参数后，提交计算。</p>'}`;};
 submit.onclick=()=>{if(!settings||!saveCurrent())return;const errors=materialPropertyIssues(settings,'generic');if(errors.length)return notify(errors[0].join('：'));submitMolecularTask(modelId,current,settings);renderTasks();notify('已提交本地演示计算，模型与参数快照已保存');};
 const taskClick=e=>{if(e.target.closest('[data-molecular-tasks]'))return navigate('/tasks');const b=e.target.closest('[data-molecular-task]');if(!b)return;const t=molecularTasks().find(t=>t.id===b.dataset.molecularTask);if(t)openDialog(`<div class="dialog-form"><h2>${esc(t.name)}</h2><p>${esc(t.status)} · 本次输入快照只读</p><pre class="task-log">${esc(JSON.stringify(t.params,null,2))}</pre><div class="dialog-actions"><button class="btn" data-dialog-close>关闭</button></div></div>`);};root.addEventListener('click',taskClick);renderTasks();const clock=setInterval(renderTasks,2000);

 view.querySelector('[data-micro-name]').addEventListener('input',e=>root.querySelector('.molecular-page-bar strong').textContent=e.target.value);
 return ()=>{clearInterval(clock);root.removeEventListener('click',taskClick);cleanup();};
}
